using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using FitnessTracker.Api.Models;using Microsoft.IdentityModel.Tokens;
namespace FitnessTracker.Api.Services;
public sealed class TokenService(IConfiguration config){public string Create(User user){var claims=new[]{new Claim(ClaimTypes.NameIdentifier,user.Id.ToString()),new Claim(ClaimTypes.Email,user.Email),new Claim(ClaimTypes.Name,user.DisplayName)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!));var token=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddMinutes(int.Parse(config["Jwt:ExpiryMinutes"]??"1440")),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));return new JwtSecurityTokenHandler().WriteToken(token);}}
